const translationEntriesEs = Object.entries(translationsEs).sort((a, b) => b[0].length - a[0].length);
const translateEs = value => {
    let translated = translationsEs[value] ?? value;
    if (translated !== value) return translated;
    for (const [source, target] of translationEntriesEs) {
        if (source.length >= 5 && translated.includes(source)) {
            translated = translated.replaceAll(source, target);
        }
    }
    return translated;
};

function translateNode(node) {
    if (node.nodeType === Node.TEXT_NODE) {
        const text = node.nodeValue;
        const trimmed = text.trim();
        const translated = translateEs(trimmed);
        if (translated !== trimmed) {
            node.nodeValue = text.replace(trimmed, translated);
        }
        return;
    }
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    for (const attr of ["aria-label", "title", "placeholder", "alt", "content", "value"]) {
        const value = node.getAttribute(attr);
        if (value) {
            const translated = translateEs(value);
            if (translated !== value) node.setAttribute(attr, translated);
        }
    }
    for (const child of node.childNodes) translateNode(child);
}

const spanishMode = new URLSearchParams(window.location.search).get("lang") === "es";
document.documentElement.lang = spanishMode ? "es" : "en";

const languageToggle = document.getElementById("language-toggle") || document.createElement("a");
if (!languageToggle.id) {
    languageToggle.id = "language-toggle";
    languageToggle.style.cssText = "display:inline-flex;align-items:center;justify-content:center;white-space:nowrap;padding:8px 12px;border:1px solid currentColor;border-radius:999px;text-decoration:none;font:600 12px Arial,sans-serif;pointer-events:auto;background:rgba(127,127,127,.08)";
    const header = document.querySelector(".header-right") || document.querySelector("header");
    if (header) header.append(languageToggle);
}
const languageUrl = new URL(window.location.href);
languageUrl.searchParams.set("lang", spanishMode ? "en" : "es");
languageToggle.href = `${languageUrl.pathname}${languageUrl.search}${languageUrl.hash}`;
languageToggle.textContent = spanishMode ? "English" : "Spanish";
languageToggle.lang = spanishMode ? "en" : "es";
languageToggle.setAttribute("aria-label", spanishMode ? "Switch language to English" : "Switch language to Spanish");

const canonicalPages = new Map([
    ["index.html", "index.html"],
    ["index_es.html", "index.html"],
    ["Chatgpt3b.html", "Chatgpt3b.html"],
    ["Chatgpt3b_es.html", "Chatgpt3b.html"],
    ["gem_3d_cardiovascular_explorer.html", "gem_3d_cardiovascular_explorer.html"],
    ["gem_3d_cardiovascular_explorer_es.html", "gem_3d_cardiovascular_explorer.html"],
    ["gem_3d_neuron.html", "gem_3d_neuron.html"],
    ["gem_3d_neuron_es.html", "gem_3d_neuron.html"]
]);
for (const link of document.querySelectorAll("a[href]")) {
    if (link === languageToggle) continue;
    const target = new URL(link.href, window.location.href);
    if (target.origin !== window.location.origin) continue;
    const canonicalPage = canonicalPages.get(target.pathname.split("/").pop());
    if (!canonicalPage) continue;
    target.pathname = new URL(`./${canonicalPage}`, window.location.href).pathname;
    target.searchParams.delete("lang");
    if (spanishMode) target.searchParams.set("lang", "es");
    link.href = `${target.pathname}${target.search}${target.hash}`;
}

if (spanishMode) {
    translateNode(document.documentElement);
    new MutationObserver(records => {
        for (const record of records) {
            if (record.type === "attributes") translateNode(record.target);
            else for (const node of record.addedNodes) translateNode(node);
            if (record.type === "characterData") translateNode(record.target);
        }
    }).observe(document.documentElement, {
        subtree: true,
        childList: true,
        characterData: true,
        attributes: true,
        attributeFilter: ["aria-label", "title", "placeholder", "alt", "content", "value"]
    });
    if (window.CanvasRenderingContext2D) {
        const fillText = CanvasRenderingContext2D.prototype.fillText;
        CanvasRenderingContext2D.prototype.fillText = function (text, ...args) {
            return fillText.call(this, translateEs(String(text)), ...args);
        };
    }
}
